310		public static String getShortAlias(NotificationAttrNode node) {
311			switch (node.getAnnType()) {
312				case CLASS:
313					return ((ClassNode) node).getClassInfo().getAliasShortName();
314				case METHOD: {
315					MethodNode mth = (MethodNode) node;
316					RootNode root = mth.root();
317					String args = mth.getMethodInfo().getArgumentsTypes().stream()
318							.map(type -> TypeGen.signature(ArgType.tryToResolveClassAlias(root, type)))
319							.collect(Collectors.joining());
320					return mth.getAlias() + '(' + args + ')'
321							+ TypeGen.signature(ArgType.tryToResolveClassAlias(root, mth.getMethodInfo().getReturnType()));
322				}
323				case FIELD: {
324					FieldInfo fldInfo = ((FieldNode) node).getFieldInfo();
325					return fldInfo.getAlias() + ':' + TypeGen.signature(ArgType.tryToResolveClassAlias(node.root(), fldInfo.getType()));
326				}
327				default:
328					throw new IllegalArgumentException("Unexpected type: " + node.getAnnType());
329			}
330		}
